def apply_styling(row_id, column_name, value):
    row = int(row_id)
    column = int(column_name)
    r = row / 8 * 12
    g = column / 2 * 32
    b = (row + column) / 10 * 16
    return {
        "backgroundColor": f"rgb({r % 256}, {g % 256}, {b % 256})",
        "color": "white"
        if (r * 0.299 + g * 0.587 + b * 0.114) < 186
        else "black",
    }


